import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const q=JSON.parse('{"title":"美国运通（American Express）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/美国运通.md","filePath":"03_companies/美国运通.md"}'),l={name:"03_companies/美国运通.md"};function i(d,a,h,n,s,u){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="美国运通-american-express" tabindex="-1">美国运通（American Express） <a class="header-anchor" href="#美国运通-american-express" aria-label="Permalink to &quot;美国运通（American Express）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>American Express Company (Amex)</td></tr><tr><td>行业</td><td>金融服务 / 支付</td></tr><tr><td>成立年份</td><td>1850年</td></tr><tr><td>总部</td><td>纽约州纽约市</td></tr><tr><td>伯克希尔持股</td><td>约 20%（长期持有）</td></tr><tr><td>首次投资</td><td>1960年代（色拉油丑闻后）</td></tr><tr><td>代表性投资</td><td>1990年代重新买入并长期持有</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>美国运通是全球领先的金融服务公司，主要业务包括：</p><ul><li><strong>支付网络</strong>：运营全球性信用卡及支付网络，与 Visa、Mastercard 竞争</li><li><strong>信用卡业务</strong>：发行个人及企业信用卡，提供消费信贷</li><li><strong>旅行服务</strong>：商务旅行管理、旅游服务（公司传统优势领域）</li><li><strong>财富管理</strong>：资产管理、投资咨询等增值服务</li></ul><p>美国运通以&quot;只服务优质客户&quot;著称，持卡人多为高收入群体，拥有强大的品牌溢价能力和较高的卡片年费收入。</p><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><h3 id="第一次投资-1960年代" tabindex="-1">第一次投资（1960年代） <a class="header-anchor" href="#第一次投资-1960年代" aria-label="Permalink to &quot;第一次投资（1960年代）&quot;">​</a></h3><p>1963-1964年间，美国运通爆发了著名的<strong>色拉油丑闻</strong>（ salad oil scandal）。公司被发现在油脂存货上存在欺诈行为，对外披露了巨额负债，股价从约60美元暴跌至约30美元以下，公司面临生存危机。</p><p>巴菲特在仔细研究后认为：</p><blockquote><p>美国运通的核心业务——支付网络和信用卡业务——并未受到根本性损害，公司的&quot;纸&quot;（信用）仍然完好无损。</p></blockquote><p>巴菲特将这次投资与他投资<strong>美国运通与运通公司的前身</strong>时所做的&quot;品质测试&quot;相类比，认为运通拥有宝贵的&quot;名声&quot;资产。最终，伯克希尔在美国运通上投入了约 35% 的总资产，最终获利约 200%（按彼时美元计）。</p><h3 id="重新投资-1990年代起" tabindex="-1">重新投资（1990年代起） <a class="header-anchor" href="#重新投资-1990年代起" aria-label="Permalink to &quot;重新投资（1990年代起）&quot;">​</a></h3><p>1990年代，巴菲特重新买入美国运通股票，并将其作为长期核心持仓持有至今。这是巴菲特最早的大赢家之一，跨越半个世纪的投资再次证明了其对品牌护城河和消费者特许权的深刻理解。</p><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><h3 id="_1-强大的品牌与声誉" tabindex="-1">1. 强大的品牌与声誉 <a class="header-anchor" href="#_1-强大的品牌与声誉" aria-label="Permalink to &quot;1. 强大的品牌与声誉&quot;">​</a></h3><ul><li>&quot;运通卡&quot;在全球范围内享有极高认知度</li><li>高端品牌形象深入人心</li><li>持卡人品牌忠诚度高</li></ul><h3 id="_2-高价值客户群体" tabindex="-1">2. 高价值客户群体 <a class="header-anchor" href="#_2-高价值客户群体" aria-label="Permalink to &quot;2. 高价值客户群体&quot;">​</a></h3><ul><li>服务于高收入、高消费群体</li><li>商旅人士首选支付工具</li><li>客户生命周期价值（LTV）高</li></ul><h3 id="_3-网络效应" tabindex="-1">3. 网络效应 <a class="header-anchor" href="#_3-网络效应" aria-label="Permalink to &quot;3. 网络效应&quot;">​</a></h3><ul><li>受理商户网络覆盖全球</li><li>发卡量与商户网络相互强化</li><li>闭环支付系统带来更高利润率</li></ul><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;美国运通的业务本质上是在交易中使用&#39;美国运通&#39;这三个字的权利。&quot; —— 1967年</p></blockquote><blockquote><p>&quot;美国运通做的事情与可口可乐和吉列没什么不同——它们都在销售&#39;品牌&#39;。&quot; —— 股东信</p></blockquote><blockquote><p>&quot;美国运通的竞争优势来源于它的名声，以及人们愿意为这种名声支付溢价。&quot; —— 1990年代</p></blockquote><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1967, 1991, 1993, 1995, 1999, 2002, 2003, 2005, 2007, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> - 投资主体</li><li><a href="./喜诗糖果.html">喜诗糖果</a> - 同期经典收购案例</li><li><a href="./可口可乐.html">可口可乐</a> - 同期重要持仓</li></ul><hr><p><em>最后更新：2026-04-12</em></p>',32)])])}const p=t(l,[["render",i]]);export{q as __pageData,p as default};
